L40_1.m_Talk_KOREA = "그리고 망할 년이라니…! 저를 언제 본 적이 있다고 그런 막말을 하시는 거죠?"
L40_1.m_fTalkTime = 0.03
L40_1.m_Talk_JPN = "それに、クソ女だなんて……！　私と初対面なのに、どうしてそんな言い方をするのですか？"
L40_1.m_Talk_ENG = "And calling me a damn woman...?! Why are you talking about me like we've met me before?!"
L41_1 = "還有，叫我該死的女人……？！你幹嘛一副好像以前見過我的口氣？！"
L40_1.m_Talk_TWN = L41_1
