L42_1 = "저는 한 번 본 사람을 잊지 않아요. 당신 같은 사람은 오늘 처음 본다고요!"
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "私は一度会った人は忘れません。あなたみたいな人は今日初めて会いました！"
L41_1.m_Talk_JPN = L42_1
L42_1 = "I never forget a face. And I'm seeing yours for the first time today!"
L41_1.m_Talk_ENG = L42_1
L42_1 = "我從不會忘記一張臉。而我今天可是第一次見到你！"
L41_1.m_Talk_TWN = L42_1
L42_1 = "我从不忘记见过的人。像你这样的人，今天可是第一次见到呢！"
