L43_1 = "하긴, 그런 천박한 옷차림에 상스러운 문신을 새긴 여자라면 누구라도 잊을 수 없겠지만……!"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "まあ、そのようにだらしない服装に下品なタトゥーをしている女なら、私でなくても忘れられないでしょうけど……！"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I'd never forget someone dressed so trashy with those vulgar tattoos...!"
L42_1.m_Talk_ENG = L43_1
L43_1 = "我怎麼可能忘掉一個穿得這麼廉價、身上還有那些低俗刺青的人……！"
L42_1.m_Talk_TWN = L43_1
L43_1 = "确实，那种穿着暴露、纹着粗俗纹身的女人，谁都不会忘记！"
