L50_1 = "저는 배우랍니다. 식사용 나이프 외에는 제대로 된 칼을 쥐어 본 적도 없는 걸요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "私は俳優です。食事用のナイフ以外に刃物らしい刃物を握ったことはありませんから。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "I'm an actress, you know. The only knife I've ever held is a dinner knife."
L49_1.m_Talk_ENG = L50_1
L50_1 = "我是個演員。除了餐刀以外，我還從來沒有拿過真正的刀呢。"
