L8_1 = "저 모습이 위장이라고 해도, 뭐 하러 자기 어린 모습으로 위장한다는 거야?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "あの姿が偽装だとしても、どうして自分の小さい頃の姿に偽装するの？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Even if it's a disguise, why would she disguise herself as a younger version of herself?"
L7_1.m_Talk_ENG = L8_1
