L7_1.m_Talk_TWN = L8_1
L8_1 = "即使那副模样是伪装，为什么要伪装成自己小时候的样子呢？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Even if it's a disguise, why would she disguise herself as a younger version of herself?"
L7_1.m_Talk_DEU = L8_1
