L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "L"
L39_1 = "이야기를 종합하면, 아무래도 자네들의 세계와 우리 세계는 다른 역사를 가진 모양이야."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "話をまとめると、どうやら君たちの世界と私たちの世界は違う歴史を持っているようだ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Judging from everything you've said, it seems your world and ours have followed different histories."
L38_1.m_Talk_ENG = L39_1
L39_1 = "綜合來看，你們的世界和我們的世界似乎有著不同的歷史。"
L38_1.m_Talk_TWN = L39_1
