L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "L"
L40_1 = "그렇다면, 이건 분기로 나뉘어진 <color=#ffd34c>평행 세계</color>일지도 모르겠군."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "なら、これは分岐によって分かれた<color=#ffd34c>パラレルワールド</color>なのかもしれないな。"
