L15_1.m_CharStrID = L16_1
L16_1 = "그건, 이 세계에 마석이 나타난 지 얼마 지나지 않은 시점이었어."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "あれは、この世界に魔石が現れて間もない頃だった。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "It was shortly after Mana Stones first began appearing in this world."
L15_1.m_Talk_ENG = L16_1
L16_1 = "那是在這個世界出現魔石不久之後的事情。"
