L17_1 = "ABBERLINE_SWANSONG_NPC_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "물론, 처음에는 믿지 않았지. 그 이방인의 말은 너무나 허황된 것들이었거든."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "もちろん、最初は信じられなかった。その異邦人の話は突拍子もないことばかりだったからな。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Naturally, I didn't believe it at first. The claims that outsider made were utterly absurd."
L16_1.m_Talk_ENG = L17_1
L17_1 = "當然，一開始我是不相信的。那個外邦人的話實在是太荒謬了。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "当然，一开始我是不相信的。那个异乡人的话实在是太荒诞了。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Naturally, I didn't believe it at first. The claims that outsider made were utterly absurd."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Naturally, I didn't believe it at first. The claims that outsider made were utterly absurd."
L16_1.m_Talk_FRA = L17_1
