L17_1.m_CharStrID = L18_1
L18_1 = "하지만 나와 파트너는 여러 사건들을 해결해가면서……."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "だが、パートナーと様々な事件を解決していく中で……"
L17_1.m_Talk_JPN = L18_1
L18_1 = "But as my partner and I solved case after case..."
L17_1.m_Talk_ENG = L18_1
L18_1 = "但是我和搭檔在解決各種事件的過程中……"
L17_1.m_Talk_TWN = L18_1
