L19_1 = "EP13_ACT4_INTERLUDE1@77#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 610
L18_1.m_CutScenStrID = "EP13_ACT4_INTERLUDE1"
