L19_1 = "ABBERLINE_SWANSONG_NPC_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "우리가 살고 있는 이 세계에 이성과 상식 밖의 <color=#ffd34c>어떤 법칙</color>이 존재한다는 것을 깨닫게 되었네."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "私たちが暮らしているこの世界に、理性と常識を逸脱した<color=#ffd34c>ある法則</color>が存在しているという事実に気づいたんだ。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "We came to understand that our world operates under <color=#ffd34c>laws</color> beyond reason and common sense."
L18_1.m_Talk_ENG = L19_1
L19_1 = "我們生活的這個世界中，存在著超越理性和常識的<color=#ffd34c>某種法則</color>。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "我们生活的这个世界中，存在着超越理性和常识的<color=#ffd34c>某种法则</color>。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "We came to understand that our world operates under <color=#ffd34c>laws</color> beyond reason and common sense."
L18_1.m_Talk_DEU = L19_1
L19_1 = "We came to understand that our world operates under <color=#ffd34c>laws</color> beyond reason and common sense."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
