L19_1.m_CharStrID = L20_1
L20_1 = "그래, 이를 테면 마석과 이능력자, 증표……."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "そう、たとえば魔石と異能力者、印……"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Things like Mana Stones, supernaturals, and marks......"
L19_1.m_Talk_ENG = L20_1
L20_1 = "是的，比如魔石、超能力者、印記……"
L19_1.m_Talk_TWN = L20_1
L20_1 = "是的，比如魔石,能力者还有徽章……"
