L20_1.m_CharStrID = L21_1
L21_1 = "그리고 평행 세계의 존재 역시 그자가 말했던 세계를 만드는 법칙의 일부라고 할 수 있겠지."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "そしてパラレルワールドの存在もまた、あの者が言っていた世界を作る法則の一部だと言えるだろう。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "And the existence of parallel worlds too was part of the law of creating a world that outsider spoke of."
L20_1.m_Talk_ENG = L21_1
L21_1 = "而且，平行世界的存在，也可以說是他所說的創造世界的法則的一部分吧。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "而且，平行世界的存在也可以说是他所说的创造世界的规则的一部分吧。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "And the existence of parallel worlds too was part of the law of creating a world that outsider spoke of."
L20_1.m_Talk_DEU = L21_1
