L31_1 = "후후, 같은 개념이라도 각 세계마다 명칭의 차이가 있다는 점은 꽤 흥미롭군."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "ふふ、同じ概念でも世界が違えば名称も違うというのはなかなか興味深いな。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Haha, it's fascinating how the same concepts can go by different names across worlds."
L30_1.m_Talk_ENG = L31_1
L31_1 = "呵呵，即使是相同的概念，每個世界的名稱差異也相當有趣。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "呵呵，即使是相同的概念，每个世界的名称差异也相当有趣。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Haha, it's fascinating how the same concepts can go by different names across worlds."
