L35_1 = "자네들의 말대로라면, 이 세계는 한 차례 멸망한 뒤 다시 원래대로 돌아왔다는 뜻이야."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "君たちの話どおりだすると、この世界は一度滅亡した後にまた元どおりに戻ったということになる。"
